221		}
222		clk.t = utc(2026, 3, 1, 0, 0)
223		febBill, err := s.CreateBill("u", feb(2026))
224		if err != nil {
225			t.Fatal(err)
226		}
227		if febBill.Terms.PlanID != "b" || febBill.MonthlyFee != 2000 || febBill.OverageUnits != 5 || febBill.OverageFee != 1000 || febBill.TotalDue != 3000 {
228			t.Fatalf("feb bill mixed terms: %+v", febBill)
229		}
230		// 1 月账单不受 2 月出账影响。
231		gotJan, _ := s.GetBill("u", jan(2026))
232		if gotJan.TotalUsage != 20 || gotJan.TotalDue != 2000 {
