194	// TestCancelSubscriptionErrors 覆盖不能取消的情形。
195	func TestCancelSubscriptionErrors(t *testing.T) {
196		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
197		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
