226	// TestCancelWhileSuspended 欠费停用不妨碍取消，也不免除债务。
227	func TestCancelWhileSuspended(t *testing.T) {
228		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
229		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
230		mustAccount(t, s, "u")
231		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
232		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "e", At: utc(2026, 1, 10, 0, 0), Quantity: 1}); err != nil {
233			t.Fatal(err)
234		}
235		clk.t = utc(2026, 2, 1, 0, 0)
236		if _, err := s.CreateBill("u", jan(2026)); err != nil {
237			t.Fatal(err)
238		}
239		clk.t = utc(2026, 2, 8, 0, 0)
240		st, _ := s.Status("u")
241		if !st.Suspended {
242			t.Fatal("should be suspended")
243		}
244	
245		// 停用期间仍可取消。
246		r := mustCancel(t, s, "u")
247		if !r.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
248			t.Fatalf("suspended cancel end = %v", r.Cancellation.EndAt)
249		}
250		st, _ = s.Status("u")
251		if !st.Suspended || !st.Subscribed {
252			t.Fatalf("cancel changed suspension/debt: %+v", st)
253		}
254		// 终止后欠费依旧存在。
255		clk.t = utc(2026, 3, 1, 0, 0)
256		st, _ = s.Status("u")
257		if st.Subscribed || !st.Suspended {
258			t.Fatalf("debt cleared at end: %+v", st)
259		}
260		if len(st.Bills) != 1 || st.Bills[0].Balance != 1000 {
261			t.Fatalf("bill missing after end: %+v", st.Bills)
262		}
263		// 结清只解除停用，不复活已取消的订阅。
264		if _, err := s.RecordPayment("u", "p", jan(2026), 1000); err != nil {
265			t.Fatal(err)
266		}
267		st, _ = s.Status("u")
268		if st.Suspended || st.Subscribed {
269			t.Fatalf("payment revived subscription: %+v", st)
270		}
271	}
